describe("detached Foundation consumer partitions", () => {
  let fixture: FoundationFixture | undefined;
  afterEach(async () => {
    await fixture?.store.close();
    fixture = undefined;
  });

  it("T-E06-D01 leaves excluded queued work intact before unavailable-adapter or tampered-plan validation", async () => {
    fixture = await foundationFixture();
    const plan = await fixturePlan(fixture);
    const run = await fixture.engine.enqueue(owner, plan.id, randomUUID());
    await fixture.store.db
      .update(schema.executionPlans)
      .set({ hash: "changed" })
      .where(eq(schema.executionPlans.id, plan.id));
    const other = new FoundationEngine(fixture.store, {
      now: fixture.clock.now,
      consumer: { excludedAdapterIds: new Set([fixture.provider.adapter.id]) },
    });

    expect(await other.tick("detached-controller")).toBe(false);

    expect(await fixture.engine.getRun(owner, run.id)).toMatchObject({
      status: "queued",
      fence: 0,
    });
    expect(await fixture.engine.getBudget(owner, fixture.project.id)).toMatchObject({
      reservedMicros: 50,
    });
    expect(fixture.provider.executions).toHaveLength(0);
  });

  it("T-E06-D01 an explicit allowlist never consumes unrelated queued adapters", async () => {
    fixture = await foundationFixture();
    const plan = await fixturePlan(fixture);
    const run = await fixture.engine.enqueue(owner, plan.id, randomUUID());
    const onlyJobs = new FoundationEngine(fixture.store, {
      now: fixture.clock.now,
      consumer: { adapterIds: new Set(["local.jobs"]) },
    });

    expect(await onlyJobs.tick("autonomous-jobs-only")).toBe(false);

    expect(await fixture.engine.getRun(owner, run.id)).toMatchObject({
      status: "queued",
      fence: 0,
    });
    expect(await fixture.engine.tick("qualified-own-consumer")).toBe(true);
    expect(await fixture.engine.getRun(owner, run.id)).toMatchObject({ status: "succeeded" });
    expect(fixture.provider.executions).toHaveLength(1);
  });

  it("T-E06-D01 an empty allowlist and exclusion precedence cannot accidentally broaden consumption", async () => {
    fixture = await foundationFixture();
    const plan = await fixturePlan(fixture);
    const run = await fixture.engine.enqueue(owner, plan.id, randomUUID());
    const empty = new FoundationEngine(fixture.store, {
      now: fixture.clock.now,
      adapters: [fixture.provider.adapter],
      consumer: { adapterIds: new Set() },
    });
    const excluded = new FoundationEngine(fixture.store, {
      now: fixture.clock.now,
      adapters: [fixture.provider.adapter],
      consumer: {
        adapterIds: new Set([fixture.provider.adapter.id]),
        excludedAdapterIds: new Set([fixture.provider.adapter.id]),
      },
    });

    expect(await empty.tick("empty-consumer")).toBe(false);
    expect(await excluded.tick("excluded-consumer")).toBe(false);

    expect(await fixture.engine.getRun(owner, run.id)).toMatchObject({
      status: "queued",
      fence: 0,
    });
    expect(fixture.provider.executions).toHaveLength(0);
  });

  it("T-E06-D01 skips another consumer's expired lease without revoking its grants or changing uncertainty", async () => {
    fixture = await foundationFixture({ leaseMs: 1000 });
    const plan = await fixturePlan(fixture);
    const run = await fixture.engine.enqueue(owner, plan.id, randomUUID());
    const context = await fixture.engine.claim("original-authority");
    if (!context) throw new Error("Claimed partition fixture missing");
    fixture.clock.advance(1001);
    const other = new FoundationEngine(fixture.store, {
      now: fixture.clock.now,
      consumer: { adapterIds: new Set(["local.jobs"]) },
    });

    expect(await other.reconcileExpired()).toBe(0);
    expect(await other.tick("foreign-lease-consumer")).toBe(false);

    expect(await fixture.engine.getRun(owner, run.id)).toMatchObject({
      status: "running",
      fence: context.fence,
    });
    expect(await fixture.engine.getGrant(owner, context.grantId)).toMatchObject({
      revokedAt: null,
    });
    expect(await fixture.engine.reconcileExpired()).toBe(1);
    expect(await fixture.engine.getRun(owner, run.id)).toMatchObject({ status: "unknown" });
  });
});

describe("autonomous job environment partition", () => {
  let fixture: JobsFixture | undefined;
  afterEach(async () => {
    await fixture?.store.close();
    fixture = undefined;
  });

  it("T-E06-D01 schedules and dispatches only selected environments even when handler names overlap", async () => {
    fixture = await jobsFixture();
    const first = await fixture.register({ trigger: { kind: "cron", cron: "*/5 * * * *" } });
    const second = await fixture.register({
      environmentId: fixture.production.id,
      expectedEnvironmentRevision: fixture.production.revision,
      trigger: { kind: "cron", cron: "*/5 * * * *" },
    });
    const selected = new InfrastructureEngine(fixture.store, {
      ...fixture.configuration,
      foundationConsumer: { adapterIds: new Set(["local.jobs"]) },
      jobs: {
        handlers: new Map([["fixture.work", fixture.handler]]),
        managedEnvironmentIds: new Set([fixture.development.id]),
      },
    });
    fixture.clock.advance(5 * 60_000);

    await selected.jobs.tick();
    await selected.foundation.tick("selected-environment-worker");
    await selected.jobs.tick();

    const overview = await fixture.jobs().overview(fixture.freshOwner());
    expect(overview.runs).toHaveLength(1);
    expect(overview.runs[0]).toMatchObject({ definitionId: first.id, state: "succeeded" });
    expect(overview.definitions.find((item) => item.id === second.id)?.nextFireAt).toBe(
      "2026-11-11T12:05:00.000Z",
    );
    expect(fixture.handler.calls.map((call) => call.environmentId)).toEqual([
      fixture.development.id,
    ]);
  });

  it("T-E06-D01 dispatches outbox only for the supervisor's managed cells", async () => {
    fixture = await jobsFixture();
    await fixture.jobs().transact(async (tx) => {
      await fixture?.jobs().enqueueOutbox(tx, fixture.intent("own-cell-outbox"));
      if (!fixture) throw new Error("Job partition fixture missing");
      await fixture.jobs().enqueueOutbox(tx, {
        ...fixture.intent("foreign-cell-outbox"),
        environmentId: fixture.production.id,
      });
    });
    const selected = new InfrastructureEngine(fixture.store, {
      ...fixture.configuration,
      jobs: {
        senders: new Map([["fixture.sink", fixture.sender]]),
        managedEnvironmentIds: new Set([fixture.development.id]),
      },
    });

    await selected.jobs.tick();

    expect(fixture.sender.sends.map((send) => send.environmentId)).toEqual([
      fixture.development.id,
    ]);
    const rows = await fixture.outboxRows();
    expect(rows.find((row) => row.effectKey === "own-cell-outbox")?.state).toBe("delivered");
    expect(rows.find((row) => row.effectKey === "foreign-cell-outbox")?.state).toBe("pending");
  });

  it("T-E06-D01 never claims an already-dispatched same-adapter run in another environment", async () => {
    fixture = await jobsFixture();
    const definition = await fixture.register({
      environmentId: fixture.production.id,
      expectedEnvironmentRevision: fixture.production.revision,
    });
    const run = await fixture.trigger(definition.id, definition.revision, "foreign-dispatched-run");
    await fixture.jobs().tick();
    const queued = await fixture.state(run.id);
    if (!queued.runId) throw new Error("Dispatched foreign fixture missing");
    const selected = new InfrastructureEngine(fixture.store, {
      ...fixture.configuration,
      foundationConsumer: {
        adapterIds: new Set(["local.jobs"]),
        environmentIds: new Set([fixture.development.id]),
      },
      jobs: {
        handlers: new Map([["fixture.work", fixture.handler]]),
        managedEnvironmentIds: new Set([fixture.development.id]),
      },
    });

    expect(await selected.foundation.tick("selected-environment-consumer")).toBe(false);

    expect(await fixture.infrastructure.foundation.getRun(owner, queued.runId)).toMatchObject({
      status: "queued",
      fence: 0,
    });
    expect(fixture.handler.calls).toHaveLength(0);
  });

  it("T-E06-D01 never reconciles an expired same-adapter lease belonging to another environment", async () => {
    fixture = await jobsFixture();
    const definition = await fixture.register({
      environmentId: fixture.production.id,
      expectedEnvironmentRevision: fixture.production.revision,
    });
    const run = await fixture.trigger(definition.id, definition.revision, "foreign-expired-run");
    await fixture.jobs().tick();
    const context = await fixture.infrastructure.foundation.claim("foreign-original-worker");
    if (!context) throw new Error("Foreign active lease fixture missing");
    fixture.clock.advance(120_000);
    const selected = new InfrastructureEngine(fixture.store, {
      ...fixture.configuration,
      foundationConsumer: {
        adapterIds: new Set(["local.jobs"]),
        environmentIds: new Set([fixture.development.id]),
      },
      jobs: { managedEnvironmentIds: new Set([fixture.development.id]) },
    });

    expect(await selected.foundation.reconcileExpired()).toBe(0);

    expect(await fixture.infrastructure.foundation.getRun(owner, context.runId)).toMatchObject({
      status: "running",
      fence: context.fence,
    });
    expect(await fixture.infrastructure.foundation.getGrant(owner, context.grantId)).toMatchObject({
      revokedAt: null,
    });
    expect((await fixture.state(run.id)).runId).toBe(context.runId);
    expect(await fixture.infrastructure.foundation.reconcileExpired()).toBe(1);
  });
});
